namespace sv_ff203d336de64c558b79898b22727846.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Each circuit gets its own instance, so users see independent data.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired when new alert data arrives. Subscribers must wrap StateHasChanged
    /// in InvokeAsync since this fires from a timer thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Simulates a database query returning a random low-stock count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by components that want polling active. Polling starts on first subscriber.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Called when a component disposes. Polling stops when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _timer?.Dispose();
            _timer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        LowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        _timer?.Dispose();
        _timer = null;
    }
}

