@page "/dashboard"
@using sv_ff203d336de64c558b79898b22727846.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>@WarehouseState.SelectedWarehouseName</strong>
    </div>
    <div class="card-body">
        <h5 class="card-title">Inventory Alerts</h5>
        <p class="card-text">
            Items below minimum stock level:
            <span class="fs-3 fw-bold @(AlertService.LowStockCount > 0 ? "text-warning" : "text-success")">
                @AlertService.LowStockCount
            </span>
        </p>
        <p class="text-muted small">
            Polling every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="alert alert-info">
    <strong>How this works:</strong> This page starts polling when you navigate here and stops when you leave.
    The alert badge in the sidebar also updates automatically because both components subscribe to
    <code>InventoryAlertService.OnAlertDataChanged</code>.
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to alert data changes
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertDataChanged += _alertHandler;

        // Subscribe to warehouse changes so we re-render the header
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling — this is the trigger for the 10-second interval
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

